/**
 * Lists the namespaces in prefix order and changes them. {@code action=save} sets {@code prefix} to {@code namespace}
 * and, with a different {@code previousPrefix}, removes that one (a rename); {@code action=delete} removes
 * {@code prefix}. Both redirect to the listing, or answer 400 with an error message when the prefix or the namespace is
 * not valid. A request without {@code action} keeps the original behavior: an empty namespace removes the prefix.
 */
public class NamespacesServlet extends TransformationServlet {

	/** Letters, digits, '_', '-' and '.', as in a SPARQL prefix name; empty for the default namespace. */
	private static final Pattern PREFIX = Pattern.compile("[\\p{L}\\p{N}_.-]*");

	private static final String ERROR_MESSAGE = "error-message";

	@Override
	protected void doPost(WorkbenchRequest req, HttpServletResponse resp) throws Exception {
		String action = req.getParameter("action");
		boolean legacy = action == null || action.isEmpty();
		try (RepositoryConnection con = repository.getConnection()) {
			if (legacy) {
				String namespace = required(req, "namespace");
				String prefix = required(req, "prefix");
				if (!namespace.isEmpty()) {
					con.setNamespace(prefix, namespace);
				} else {
					con.removeNamespace(prefix);
				}
			} else if ("save".equals(action)) {
				String prefix = prefix(req, "prefix");
				String namespace = absoluteNamespace(req);
				String previousPrefix = req.getParameter("previousPrefix");
				con.setNamespace(prefix, namespace);
				if (previousPrefix != null && !previousPrefix.equals(prefix)) {
					con.removeNamespace(prefix(req, "previousPrefix"));
				}
			} else if ("delete".equals(action)) {
				con.removeNamespace(prefix(req, "prefix"));
			} else {
				throw new BadRequestException("Unknown action: " + action);
			}
		} catch (BadRequestException exception) {
			resp.setStatus(HttpServletResponse.SC_BAD_REQUEST);
			TupleResultBuilder builder = getTupleResultBuilder(req, resp, resp.getOutputStream());
			builder.metadata(ERROR_MESSAGE, exception.getMessage());
			service(builder);
			return;
		}
		if (legacy) {
			super.service(req, resp);
		} else {
			resp.sendRedirect("namespaces");
		}
	}

	private static String required(WorkbenchRequest req, String name) throws BadRequestException {
		String value = req.getParameter(name);
		if (value == null) {
			throw new BadRequestException("Missing " + name);
		}
		return value;
	}

	private static String prefix(WorkbenchRequest req, String name) throws BadRequestException {
		String prefix = required(req, name).trim();
		if (!PREFIX.matcher(prefix).matches()) {
			throw new BadRequestException("Invalid prefix: " + prefix
					+ " (use letters, digits, '_', '-' and '.')");
		}
		return prefix;
	}

	private static String absoluteNamespace(WorkbenchRequest req) throws BadRequestException {
		String namespace = required(req, "namespace").trim();
		try {
			if (new ParsedIRI(namespace).isAbsolute()) {
				return namespace;
			}
		} catch (URISyntaxException exception) {
			// reported below
		}
		throw new BadRequestException("The namespace must be an absolute IRI: " + namespace);
	}

	@Override
	public void service(TupleResultBuilder builder)
			throws RepositoryException, QueryResultHandlerException {
		try (RepositoryConnection con = repository.getConnection()) {
			con.setParserConfig(NON_VERIFYING_PARSER_CONFIG);
			builder.start("prefix", "namespace");
			builder.link(List.of(INFO));
			List<Namespace> namespaces = new ArrayList<>(Iterations.asList(con.getNamespaces()));
			namespaces.sort(Comparator.comparing(Namespace::getPrefix));
			for (Namespace ns : namespaces) {
				builder.result(ns.getPrefix(), ns.getName());
			}
			builder.end();
		}
	}

}
